add_filter( 'woocommerce_email_recipient_new_order', 'perfectpixel_new_order_recipient_by_country', 20, 2 );

function perfectpixel_new_order_recipient_by_country( $recipient, $order ) {
	if ( ! $order instanceof WC_Order ) {
		return $recipient;
	}
	foreach ( explode( '|', '{{new_order_country_recipients}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && strtoupper( $parts[0] ) === $order->get_billing_country() && is_email( $parts[1] ) ) {
			return 'yes' === '{{new_order_keep_default}}' ? $recipient . ',' . $parts[1] : $parts[1];
		}
	}
	return $recipient;
}
